\label{ex:identity}

In the case of the univariate identity link function, i.e.,\@ $\mu(x) = x$,
we have
$$ A(\boldsymbol \beta,\boldsymbol z_1,\boldsymbol z_2) = (1, \boldsymbol z_1^\top, \boldsymbol z_2^\top )^\top.$$
Hence the GEE  \eqref{eq:gee} takes the form
$$ \boldsymbol U(\boldsymbol \beta) = \sum_{i_1=1}^{n_1} \sum_{i_2=1}^{n_2}
    \begin{pmatrix} 1 \\\boldsymbol  Z_{1i_1} \\ \boldsymbol Z_{2i_2} \end{pmatrix}
    \Big(\tilde \theta_{i_1i_2} - \beta_0 - \boldsymbol \beta_1^\top \boldsymbol Z_{1i_1} - \boldsymbol \beta_2^\top \boldsymbol Z_{2i_2} \Big) = \boldsymbol 0, $$
which is solved by
$$  \hat{\boldsymbol \beta} := \hat{\boldsymbol \Sigma}^{-1} \hat {\boldsymbol \Psi} := \Big( \frac{1}{n_1 n_2} \sum_{i_1=1}^{n_1} \sum_{i_2=1}^{n_2} \Big(\begin{smallmatrix} 1 \\ \boldsymbol Z_{1i_1} \\\boldsymbol  Z_{2i_2} \end{smallmatrix}\Big)\Big(\begin{smallmatrix} 1 \\ \boldsymbol Z_{1i_1} \\\boldsymbol  Z_{2i_2} \end{smallmatrix} \Big)^\top \Big)^{-1} \frac{1}{n_1 n_2}  \sum_{i_1=1}^{n_1} \sum_{i_2=1}^{n_2}  \Big(\begin{smallmatrix} 1 \\ \boldsymbol Z_{1i_1} \\\boldsymbol  Z_{2i_2} \end{smallmatrix} \Big) \tilde \theta_{i_1 i_2}.$$
Here, the inverse $\hat{\boldsymbol \Sigma}^{-1}$ is to be understood as the generalized Moore-Penrose pseudo-inverse of $\hat{\boldsymbol \Sigma}$.
If the second moments of all covariates exist,  $\hat{\boldsymbol \Sigma}$ converges almost surely to
$$ \boldsymbol \Sigma :=  \text{E} \Bigg(\begin{pmatrix} 1 \\ \boldsymbol Z_{1i_1} \\ \boldsymbol Z_{2i_2} \end{pmatrix}\begin{pmatrix} 1 \\ \boldsymbol Z_{1i_1} \\ \boldsymbol Z_{2i_2} \end{pmatrix}^\top \Bigg) =  \begin{pmatrix}
    1 & \boldsymbol E_{1}^\top & \boldsymbol E_2^\top \\
    \boldsymbol E_1 & \boldsymbol \Sigma_1 + \boldsymbol E_1 \boldsymbol E_1^\top & \boldsymbol E_1 \boldsymbol E_2^\top \\
    \boldsymbol E_2 & \boldsymbol E_2 \boldsymbol E_1^\top & \boldsymbol \Sigma_2 + \boldsymbol E_2 \boldsymbol E_2^\top
\end{pmatrix}$$
with expectation vectors $\boldsymbol E_j = \text{E}(\boldsymbol Z_{j i_j}) \in \mathbb R^{p_j}$ and variance-covariance matrices $\boldsymbol \Sigma_j = \text{var}(\boldsymbol Z_{j i_j}) \in \mathbb R^{p_j \times p_j}$, $j=1,2$.
It is easy to see that $\boldsymbol \Sigma$ has full rank $p = 1 + p_1 + p_2$ whenever $\boldsymbol \Sigma_1$ and $\boldsymbol \Sigma_2$ have full ranks $p_1$ and $p_2$, respectively:
First, being the limit of a sum of positive semi-definite matrices, $\boldsymbol \Sigma$ is positive semi-definite as well; second, for all $\boldsymbol x = (x_0, \boldsymbol x_1^\top , \boldsymbol x_2^\top)^\top \in \mathbb R^{1+p_1+p_2} \setminus \{\boldsymbol 0\}$, and using the stochastic independence of $\boldsymbol Z_{1i_1} $ and $\boldsymbol Z_{2i_2}$, it holds that
\begin{align*}
   \boldsymbol x^\top \boldsymbol \Sigma \boldsymbol x
    & = \boldsymbol x^\top \text{E}\Big(\Big(\begin{smallmatrix}
    1 \\ \boldsymbol Z_{1i_1} \\ \boldsymbol Z_{2i_2} 
\end{smallmatrix} \Big)\Big(\begin{smallmatrix}
    1 \\ \boldsymbol Z_{1i_1} \\ \boldsymbol Z_{2i_2} 
\end{smallmatrix} \Big)^\top \Big) \boldsymbol x 
= \boldsymbol x^\top \Big[ \text{var}\Big(\begin{smallmatrix}
    1 \\ \boldsymbol Z_{1i_1} \\ \boldsymbol Z_{2i_2} 
\end{smallmatrix} \Big)
 +  \Big( \begin{smallmatrix}
     1 \\ \boldsymbol E_1 \\ \boldsymbol E_2
 \end{smallmatrix} \Big) \Big( \begin{smallmatrix}
     1 \\ \boldsymbol E_1 \\ \boldsymbol E_2
 \end{smallmatrix} \Big)^\top \Big] \boldsymbol x 
    \\
    & = \text{var} \Big(\boldsymbol x^\top \Big(\begin{smallmatrix}
    1 \\ \boldsymbol Z_{1i_1} \\ \boldsymbol Z_{2i_2} 
\end{smallmatrix} \Big) \Big) + \big((1, \boldsymbol E_1^\top, \boldsymbol E_2^\top)\boldsymbol x \big)^2
 = (x_0 + \boldsymbol x_1^\top \boldsymbol E_1 + \boldsymbol x_2^\top \boldsymbol E_2)^2 + \text{var}(\boldsymbol x_1^\top \boldsymbol Z_{1i_1}) + \text{var}(\boldsymbol x_2^\top \boldsymbol Z_{2i_2})\\
 & = (x_0 + \boldsymbol x_1^\top \boldsymbol E_1 + \boldsymbol x_2^\top \boldsymbol E_2)^2 + \boldsymbol x_1^\top \boldsymbol \Sigma_1 \boldsymbol x_1 + \boldsymbol x_2^\top \boldsymbol \Sigma_2 \boldsymbol x_2 > 0
\end{align*}
if $\boldsymbol \Sigma_1$ and $\boldsymbol \Sigma_2$ have full ranks.
Hence, $\boldsymbol x^\top \boldsymbol \Sigma \boldsymbol x$ equals zero only if $\boldsymbol x_j^\top \boldsymbol \Sigma_j \boldsymbol x_j = 0$, $j=1,2$. This is equivalent to $\boldsymbol x_1 = \boldsymbol x_2 = \boldsymbol 0$, implying $x_0 = 0$.
Consequently, $\boldsymbol \Sigma$ is positive definite and the probability that the  inverse of $\hat{\boldsymbol \Sigma}$ exists tends to one with increasing sample sizes.

At present, i.e., in the fully observable case, the parameter estimator reduces to
\begin{align}
    \label{eq:beta_hat_reduced}
 \hat{\boldsymbol \beta} = \hat {\boldsymbol \Sigma}^{-1} 
\Big(\hat \theta \ , \ \frac1{n_1} \sum_{i_1=1}^{n_1}\boldsymbol  Z_{1i_1}^\top \tilde \theta_{i_1 \bullet} \ , \  \frac1{n_2} \sum_{i_2=1}^{n_2} \boldsymbol Z_{2i_2}^\top \tilde \theta_{\bullet i_2}\Big)^\top
\end{align}
since $\hat \theta =  \sum_{i_1=1}^{n_1} \sum_{i_2=1}^{n_2} \tilde \theta_{i_1 i_2} / (n_1 n_2)$.
Here we used the definitions
\begin{align*}
\tilde \theta_{i_1 \bullet} & := \frac1{n_2} \sum_{i_2=1}^{n_2} \tilde \theta_{i_1 i_2} = \frac1{n_2} \sum_{i_2=1}^{n_2} 1\{T_{1i_1}> T_{2i_2}\} = 1 -\hat S_2(T_{1 i_1}-) \\\text{and} \quad \tilde \theta_{\bullet i_2} & :=  \frac{1}{n_1} \sum_{i_1=1}^{n_1} \tilde \theta_{i_1 i_2} = \frac1{n_1} \sum_{i_1=1}^{n_1} 1\{T_{1i_1}> T_{2i_2}\} = \hat S_1(T_{2 i_2}) .
\end{align*}

To analyze the asymptotic properties of $\hat{\boldsymbol \beta}$, we define 
\begin{align*}
    \boldsymbol \Omega^{(1)} \ := \   & \text{cov}\Big(\Big(\begin{smallmatrix} 1 \\ \boldsymbol Z_{1i_1} \\ \boldsymbol Z_{2i_2} \end{smallmatrix}\Big) 1\{T_{1i_1} > T_{2i_2} \}, \Big(\begin{smallmatrix} 1 \\ \boldsymbol Z_{1i_1} \\ \boldsymbol Z_{2\tilde{i}_2} \end{smallmatrix}\Big) 1\{T_{1i_1} > T_{2\tilde{i}_2} \} \Big),  \quad i_2 \neq \tilde i_2, \\
    \text{and} \quad 
\boldsymbol \Omega^{(2)} \ := \   &\text{cov}\Big(\Big(\begin{smallmatrix} 1 \\ \boldsymbol Z_{1i_1} \\ \boldsymbol Z_{2i_2} \end{smallmatrix}\Big) 1\{T_{1i_1} > T_{2i_2} \}, \Big(\begin{smallmatrix} 1 \\ \boldsymbol Z_{1\tilde{i}_1} \\ \boldsymbol Z_{2i_2} \end{smallmatrix}\Big) 1\{T_{1\tilde{i}_1} > T_{2i_2} \} \Big), \quad i_1 \neq \tilde i_1.
\end{align*}

Assuming that $n_1/(n_1+n_2) \to \lambda \in (0,1)$ as $\min(n_1,n_2) \to \infty$, that $\text{E}(\boldsymbol Z_{j i_j}^\top \boldsymbol Z_{j i_j}) < \infty$, $j=1,2$,  and that both $\boldsymbol \Omega := (1-\lambda) \boldsymbol \Omega^{(1)} + \lambda \boldsymbol \Omega^{(2)}$ and $\boldsymbol \Sigma$ have full rank $p$,
then, as $\min(n_1,n_2) \to \infty$,
$$ \sqrt{\frac{n_1 n_2}{n_1 + n_2}} \, (\hat {\boldsymbol \beta} - \boldsymbol \beta_0)  \, \stackrel d \to \, \mathcal N_p(\boldsymbol 0, \boldsymbol \Sigma^{-1}\boldsymbol  \Omega\boldsymbol  (\boldsymbol \Sigma^{-1})^\top). $$
The proof of this central limit theorem is given in Appendix \ref{app:proofs}.

In practice, this result could be used to obtain confidence regions for $\boldsymbol \beta_0$ after employing an estimator of the asymptotic variance-covariance matrix.
A consistent estimator of $\boldsymbol \Sigma$ was suggested above; a consistent estimator of $\boldsymbol \Omega$ is proposed in Appendix \ref{app:proofs}.

\label{ass:general}
\begin{enumerate}[leftmargin=1cm]
\item[] \phantom{a}\\[-.3cm]
    \item[(1.1) \ ] The function $\mu: \mathbb R \to \mathbb R$ is strictly increasing and it is three times continuously differentiable; \vspace{.08cm}
    \item[(1.2) \ ]
 for each $\boldsymbol \beta \in \mathbb R^p$ there exists the limit in probability of
 $$ C(\boldsymbol \beta) := \frac1{n_1n_2}\sum_{i_1=1}^{n_1} \sum_{i_2=1}^{n_2} (\tilde \theta_{i_1i_2} - \tfrac12 \mu_{i_1 i_2}) \,\mu_{i_1 i_2}, $$
 denoted by $f(\boldsymbol \beta)$, with $f: \mathbb R^p \to \mathbb R$ being twice continuously differentiable; \vspace{.08cm}
 \item[(1.3) \ ] for each $\boldsymbol \beta \in \mathbb R^p$ there exists the limit in probability of
 $$ \boldsymbol U(\boldsymbol \beta) = (\nabla C(\boldsymbol \beta))^\top = \frac1{n_1n_2}\sum_{i_1=1}^{n_1} \sum_{i_2=1}^{n_2} \boldsymbol A_{i_1i_2} (\tilde \theta_{i_1i_2} - \mu_{i_1 i_2}),$$
 denoted by $(\nabla f)^\top$,
 and a unique root $\boldsymbol \beta_0$ of $\nabla f$ satisfying $\nabla f(\boldsymbol \beta_0) = \boldsymbol 0$; \vspace{.08cm}
 \item[(1.4) \ ] there exists a neighborhood $B$ of $\boldsymbol \beta_0$ such that, for each $\boldsymbol \beta \in B$, the Jacobian
 $$ D \boldsymbol U(\boldsymbol \beta) = \frac1{n_1n_2}\sum_{i_1=1}^{n_1} \sum_{i_2=1}^{n_2} \Big(\boldsymbol Z_{i_1i_2} \boldsymbol Z_{i_1i_2}^\top \mu''(\boldsymbol \beta^\top \boldsymbol Z_{i_1i_2}) (\tilde \theta_{i_1i_2} - \mu_{i_1 i_2} ) - \boldsymbol A_{i_1i_2} \boldsymbol A_{i_1i_2}^\top \Big)$$
 converges in probability to some $(p \times p)$-matrix $- \check{\boldsymbol \Sigma}(\boldsymbol \beta)$, 
 which is negative definite in $\boldsymbol \beta_0$ and continuous in $\boldsymbol \beta_0$; further assume that the convergence in probability is uniform over $B$; \vspace{.08cm}
 \item[(1.5) \ ] $\sqrt{\frac{n_1n_2}{n_1+n_2}} \, \boldsymbol U(\boldsymbol \beta_0) \stackrel d \to \boldsymbol W \sim \mathcal{N}_p(\boldsymbol 0,  \check{\boldsymbol \Omega})$ for some $(p\times p)$-matrix $ \check{\boldsymbol \Omega}$.
 \end{enumerate}

\label{thm:censored}
 Let $n_1, n_2 \to \infty$ such that $\frac{n_1}{n_1+n_2} \to \lambda \in (0,1)$.
 Under Assumption~\ref{ass:general},  the solution $\hat {\boldsymbol \beta}$ of \eqref{eq:gee}
\begin{itemize}[leftmargin = 1cm]
\item[(i) \ ] exists with a probability tending to 1, \vspace{.08cm}
\item[(ii) \ ] converges to $\boldsymbol \beta_0$ in probability, and \vspace{.08cm}
\item[(iii) \ ] satisfies
 $$ \sqrt{\frac{n_1 n_2}{n_1 + n_2}} \, (\hat {\boldsymbol \beta} - \boldsymbol \beta_0) \, \stackrel d {\longrightarrow}  \, \check{\boldsymbol \Sigma}(\boldsymbol \beta_0) \boldsymbol W \, \sim \,  \mathcal N_p(\boldsymbol 0, (\check{\boldsymbol \Sigma}(\boldsymbol \beta_0))^{-1} \check{\boldsymbol \Omega} ((\check{\boldsymbol \Sigma}(\boldsymbol \beta_0))^{-1})^\top). $$
\end{itemize}
